package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Real;
    in attribute io_3 : Integer;
    in attribute io_3_valid : Boolean;
    attribute thresholdC : Real := 30.0;
    attribute fanMinPwm : Real := 0.0;
    attribute autoMode : Boolean := false;
    attribute prevOverheatCond : Boolean := false;
    perform action tick {
      first start;
      then if io_3_valid and (io_3 == 10) {
        first start;
        then assign thresholdC := 30.0;
        then assign fanMinPwm := 0.0;
        then assign autoMode := false;
        then assign prevOverheatCond := false;
      }
      then if io_3_valid and (io_3 == 7) {
        first start;
        then assign thresholdC := 0.0;
      }
      then if io_3_valid and (io_3 == 8) {
        first start;
        then assign fanMinPwm := 0.0;
      }
      then if io_3_valid and (io_3 == 11) {
        first start;
        then assign autoMode := true;
      }
      then if io_3_valid and (io_3 == 12) {
        first start;
        then assign autoMode := false;
      }
      then assign prevOverheatCond := (if io_0 >= (thresholdC + 5.0) ? true else false);
    }
    out attribute io_1 : Real = (if autoMode ? (if io_0 >= thresholdC ? (if io_0 >= (thresholdC + 5.0) ? fanMinPwm else fanMinPwm) else 0.0) else 0.0);
    out attribute io_2 : Boolean = (if autoMode and (io_0 >= (thresholdC + 5.0)) ? true else false);
    out attribute serial_0_trigger : Boolean = (if autoMode and (io_0 >= (thresholdC + 5.0)) and (not prevOverheatCond) ? true else false);
    out attribute serial_0_value_0 : Real = io_0;
  }
  part system : Controller;
}
